sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var intakeId = current.intake_case + '';
    if (!intakeId)
        return;

    // Any other task on this intake case still open? Then leave the case as-is.
    var pending = new GlideRecord('x_gegis_ins_policy_case_task');
    pending.addQuery('intake_case', intakeId);
    pending.addQuery('active', true);
    pending.addQuery('sys_id', '!=', current.getUniqueValue());
    pending.setLimit(1);
    pending.query();
    if (pending.hasNext())
        return;

    var intake = new GlideRecord('x_gegis_ins_policy_intake_case');
    if (!intake.get(intakeId))
        return;

    // Never disturb a case that has already reached a final state.
    var FINAL = 'completed,rejected,cancelled,duplicate,failed';
    if (FINAL.indexOf(intake.status + '') >= 0)
        return;

    if (intake.status + '' !== 'in_progress') {
        intake.status = 'in_progress';
        intake.work_notes = 'All associated tasks closed (last: ' + current.number +
            ') -> intake case moved to In Progress.';
        intake.update();
    }

})(current, previous);
